import{_ as l,a0 as a,w as p,s as i,I as s,x as t,a1 as e,A as r,ao as g}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"安装 Strongswan ：Linux 上一个基于 IPsec 的 VPN 工具 | LCTT x X-CMD","titleTemplate":false,"description":"安装 Strongswan ：Linux 上一个基于 IPsec 的 VPN 工具 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安装 Strongswan ：Linux 上一个基于 IPsec 的 VPN 工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安装 Strongswan ：Linux 上一个基于 IPsec 的 VPN 工具 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150205 Install Strongswan - A Tool to Setup IPsec Based VPN in Linux","title":"安装 Strongswan ：Linux 上一个基于 IPsec 的 VPN 工具","tag":"201508","desc":""},"relativePath":"201508/20150205 Install Strongswan - A Tool to Setup IPsec Based VPN in Linux.md","filePath":"[post].md"}'),u={name:"201508/20150205 Install Strongswan - A Tool to Setup IPsec Based VPN in Linux.md"};function d(w,n,m,c,x,P){const o=a("Link");return p(),i("div",null,[n[15]||(n[15]=s("h1",{id:"安装-strongswan-linux-上一个基于-ipsec-的-vpn-工具",tabindex:"-1"},[t("安装 Strongswan ：Linux 上一个基于 IPsec 的 VPN 工具 "),s("a",{class:"header-anchor",href:"#安装-strongswan-linux-上一个基于-ipsec-的-vpn-工具","aria-label":"Permalink to “安装 Strongswan ：Linux 上一个基于 IPsec 的 VPN 工具”"},"​")],-1)),n[16]||(n[16]=s("p",null,"IPsec是一个提供网络层安全的标准。它包含认证头(AH)和安全负载封装(ESP)组件。AH提供包的完整性，ESP组件提供包的保密性。IPsec确保了在网络层的安全特性。",-1)),n[17]||(n[17]=s("ul",null,[s("li",null,"保密性"),s("li",null,"数据包完整性"),s("li",null,"来源不可抵赖性"),s("li",null,"重放攻击防护")],-1)),s("p",null,[e(o,{href:"https://www.strongswan.org/"},{default:r(()=>[...n[0]||(n[0]=[t("Strongswan",-1)])]),_:1}),n[1]||(n[1]=t("是一个IPsec协议的开源代码实现，Strongswan的意思是强安全广域网（StrongS/WAN）。它支持IPsec的VPN中的两个版本的密钥自动交换（网络密钥交换（IKE）V1和V2）。",-1))]),n[18]||(n[18]=g(`<p>Strongswan基本上提供了在VPN的两个节点/网关之间自动交换密钥的共享，然后它使用了Linux内核的IPsec（AH和ESP）实现。密钥共享使用了之后用于ESP数据加密的IKE 机制。在IKE阶段，strongswan使用OpenSSL的加密算法（AES，SHA等等）和其他加密类库。无论如何，IPsec中的ESP组件使用的安全算法是由Linux内核实现的。Strongswan的主要特性如下：</p><ul><li>x.509证书或基于预共享密钥认证</li><li>支持IKEv1和IKEv2密钥交换协议</li><li>可选的，对于插件和库的内置完整性和加密测试</li><li>支持椭圆曲线DH群和ECDSA证书</li><li>在智能卡上存储RSA私钥和证书</li></ul><p>它能被使用在客户端/服务器（road warrior模式）和网关到网关的情景。</p><h3 id="如何安装" tabindex="-1">如何安装 <a class="header-anchor" href="#如何安装" aria-label="Permalink to “如何安装”">​</a></h3><p>几乎所有的Linux发行版都支持Strongswan的二进制包。在这个教程，我们会从二进制包安装strongswan，也会从源代码编译带有合适的特性的strongswan。</p><h3 id="使用二进制包" tabindex="-1">使用二进制包 <a class="header-anchor" href="#使用二进制包" aria-label="Permalink to “使用二进制包”">​</a></h3><p>可以使用以下命令安装Strongswan到Ubuntu 14.04 LTS</p><pre><code>$ sudo aptitude install strongswan
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/strongswan-binary.png" alt="安装strongswan"></p><p>strongswan的全局配置（strongswan.conf）文件和ipsec配置（ipsec.conf/ipsec.secrets）文件都在/etc/目录下。</p><h3 id="strongswan源码编译安装的依赖包" tabindex="-1">strongswan源码编译安装的依赖包 <a class="header-anchor" href="#strongswan源码编译安装的依赖包" aria-label="Permalink to “strongswan源码编译安装的依赖包”">​</a></h3><ul><li>GMP（strongswan使用的高精度数学库）</li><li>OpenSSL（加密算法来自这个库）</li><li>PKCS（1，7，8，11，12）（证书编码和智能卡集成）</li></ul><h4 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to “步骤”">​</a></h4><p><strong>1)</strong> 在终端使用下面命令到/usr/src/目录</p><pre><code>$ cd /usr/src
</code></pre><p><strong>2)</strong> 用下面命令从strongswan网站下载源代码</p><pre><code> $ sudo wget http://download.strongswan.org/strongswan-5.2.1.tar.gz
</code></pre><p>（strongswan-5.2.1.tar.gz 是当前最新版。）</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/download_strongswan.png" alt="下载软件"></p><p><strong>3)</strong> 用下面命令提取下载的软件，然后进入目录。</p><pre><code>$ sudo tar –xvzf strongswan-5.2.1.tar.gz; cd strongswan-5.2.1
</code></pre><p><strong>4)</strong> 使用configure命令配置strongswan每个想要的选项。</p><pre><code>$ ./configure --prefix=/usr/local -–enable-pkcs11 -–enable-openssl
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/strongswan-configure.png" alt="检查strongswan包"></p><p>如果GMP库没有安装，配置脚本将会发生下面的错误。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/gmp-error.png" alt="GMP library error"></p><p>因此，首先，使用下面命令安装GMP库然后执行配置脚本。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/gmp-installation1.png" alt="gmp installation"></p><p>不过，如果GMP已经安装还报上述错误的话，在Ubuntu上使用如下命令，给在路径 /usr/lib，/lib/，/usr/lib/x86_64-linux-gnu/ 下的libgmp.so库创建软连接。</p><pre><code>$ sudo ln -s /usr/lib/x86_64-linux-gnu/libgmp.so.10.1.3 /usr/lib/x86_64-linux-gnu/libgmp.so
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/softlink.png" alt="softlink of libgmp.so library"></p><p>创建libgmp.so软连接后，再执行./configure脚本也许就找到gmp库了。然而，如果gmp头文件发生其他错误，像下面这样。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/gmp-header.png" alt="GMP header file issu"></p><p>为解决上面的错误，使用下面命令安装libgmp-dev包</p><pre><code>$ sudo aptitude install libgmp-dev
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/gmp-dev.png" alt="Installation of Development library of GMP"></p><p>安装gmp的开发库后，在运行一遍配置脚本，如果没有发生错误，则将看见下面的这些输出。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/successful-run.png" alt="Output of Configure scirpt"></p><p>使用下面的命令编译安装strongswan。</p><pre><code>$ sudo make ; sudo make install 
</code></pre><p>安装strongswan后，全局配置（strongswan.conf）和ipsec策略/密码配置文件（ipsec.conf/ipsec.secretes）被放在<strong>/usr/local/etc</strong>目录。</p><p>根据我们的安全需要Strongswan可以用作隧道或者传输模式。它提供众所周知的site-2-site模式和road warrior模式的VPN。它很容易使用在Cisco，Juniper设备上。</p><hr>`,43)),s("p",null,[n[3]||(n[3]=t("via: ",-1)),e(o,{href:"http://linoxide.com/security/install-strongswan/"},{default:r(()=>[...n[2]||(n[2]=[t("http://linoxide.com/security/install-strongswan/",-1)])]),_:1})]),s("p",null,[n[7]||(n[7]=t("作者：",-1)),e(o,{href:"http://linoxide.com/author/naveeda/"},{default:r(()=>[...n[4]||(n[4]=[t("nido",-1)])]),_:1}),n[8]||(n[8]=t(" 译者：",-1)),e(o,{href:"https://github.com/wyangsun"},{default:r(()=>[...n[5]||(n[5]=[t("wyangsun",-1)])]),_:1}),n[9]||(n[9]=t(" 校对：",-1)),e(o,{href:"https://github.com/wxy"},{default:r(()=>[...n[6]||(n[6]=[t("wxy",-1)])]),_:1})]),s("p",null,[n[12]||(n[12]=t("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...n[10]||(n[10]=[t("LCTT",-1)])]),_:1}),n[13]||(n[13]=t(" 原创翻译，",-1)),e(o,{href:"http://linux.cn/"},{default:r(()=>[...n[11]||(n[11]=[t("Linux中国",-1)])]),_:1}),n[14]||(n[14]=t(" 荣誉推出",-1))])])}const I=l(u,[["render",d]]);export{b as __pageData,I as default};
